package com.nthexperience.desktop;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.media.*;
import android.net.Uri;
import android.os.*;
import android.view.Gravity;
import android.widget.*;
import java.io.*;
import java.util.*;

/** Foreground recording only. Leaving the surface finalizes the file and releases the mic. */
final class EightSoundRecorder extends LinearLayout {
    static final int PERMISSION=8502;final Activity activity;final File folder;final TextView state,record;final LinearLayout list;final ProgressBar meter;final Handler main=new Handler(Looper.getMainLooper());
    MediaRecorder recorder;MediaPlayer player;File partial;long started;boolean closed;
    final Runnable tick=new Runnable(){public void run(){if(recorder==null||closed)return;state.setText("Recording · "+EightAlarms.format(SystemClock.elapsedRealtime()-started));try{meter.setProgress(recorder.getMaxAmplitude());}catch(RuntimeException ignored){}main.postDelayed(this,200);}};
    EightSoundRecorder(Activity a){super(a);activity=a;folder=new File(a.getFilesDir(),"eight/recordings");folder.mkdirs();setOrientation(VERTICAL);setBackgroundColor(0xff9c241f);setContentDescription("Eight Sound Recorder");TenAppearance.preserve(this);
        TextView title=Aero.text(a,"Sound Recorder",32,Color.WHITE);title.setPadding(dp(24),dp(18),dp(16),dp(18));addView(title);state=Aero.text(a,"Ready to record",16,Color.WHITE);state.setPadding(dp(24),dp(8),dp(24),dp(8));state.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);addView(state);meter=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);meter.setMax(32767);meter.setContentDescription("Microphone input level");addView(meter,new LayoutParams(-1,dp(12)));record=button("Record",()->{if(recorder==null)start();else stop("Recording saved");});record.setContentDescription("Recorder start or stop");addView(record,new LayoutParams(-1,dp(64)));TextView hint=Aero.text(a,"Recording saves when you stop or leave this screen. Hold a saved recording for rename, share or delete.",13,Color.WHITE);hint.setPadding(dp(24),dp(8),dp(24),dp(16));addView(hint);ScrollView scroll=new ScrollView(a);list=Aero.column(a);list.setPadding(dp(16),0,dp(16),dp(20));scroll.addView(list);addView(scroll,new LayoutParams(-1,0,1));refresh();}
    int dp(int n){return Aero.dp(getContext(),n);}
    TextView button(String title,Runnable action){TextView b=Aero.text(activity,title,18,Color.WHITE);b.setPadding(dp(12),dp(12),dp(12),dp(12));b.setMinHeight(dp(52));b.setGravity(Gravity.CENTER_VERTICAL);b.setFocusable(true);b.setContentDescription(title);b.setOnClickListener(v->action.run());return b;}
    void start(){if(closed)return;if(activity.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){activity.requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},PERMISSION);state.setText("Allow microphone access, then tap Record.");return;}stopPlayback();MediaRecorder next=Build.VERSION.SDK_INT>=31?new MediaRecorder(activity):new MediaRecorder();File file=new File(folder,"Recording-"+System.currentTimeMillis()+".part");try{next.setAudioSource(MediaRecorder.AudioSource.MIC);next.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);next.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);next.setAudioEncodingBitRate(128000);next.setAudioSamplingRate(44100);next.setOutputFile(file.getPath());next.setMaxDuration(30*60*1000);next.setMaxFileSize(100L*1024*1024);next.setOnInfoListener((r,what,extra)->stop("Recording saved at the recording limit"));next.setOnErrorListener((r,what,extra)->stop("Recording stopped by the device"));next.prepare();next.start();recorder=next;partial=file;started=SystemClock.elapsedRealtime();record.setText("Stop and save");main.post(tick);}catch(Exception ex){next.release();file.delete();state.setText("Cannot start recording. Check microphone access and close other apps using it.");}}
    void stop(String message){if(recorder==null)return;main.removeCallbacks(tick);MediaRecorder old=recorder;recorder=null;boolean saved=false;try{old.stop();saved=partial!=null&&partial.length()>0;}catch(RuntimeException ignored){}finally{old.release();}if(partial!=null){File target=new File(folder,partial.getName().replace(".part",".m4a"));saved=saved&&partial.renameTo(target);if(!saved)partial.delete();}partial=null;record.setText("Record");meter.setProgress(0);state.setText(saved?message:"Recording was too short or interrupted. Tap Record to try again.");refresh();}
    void refresh(){if(closed)return;list.removeAllViews();File[] files=folder.listFiles((dir,name)->name.endsWith(".m4a"));if(files==null||files.length==0){list.addView(Aero.text(activity,"Your saved recordings will appear here.",15,Color.WHITE));return;}Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());for(File file:files){TextView row=button(file.getName()+"\n"+android.text.format.Formatter.formatShortFileSize(activity,file.length()),()->play(file));row.setContentDescription("Play recording "+file.getName());row.setOnLongClickListener(v->{commands(file);return true;});row.setOnContextClickListener(v->{commands(file);return true;});list.addView(row);}}
    void play(File file){if(recorder!=null){state.setText("Stop recording before playback.");return;}stopPlayback();MediaPlayer next=new MediaPlayer();player=next;try{next.setDataSource(file.getPath());next.setOnPreparedListener(p->{if(player==p&&!closed){p.start();state.setText("Playing · "+file.getName());}});next.setOnCompletionListener(p->{stopPlayback();state.setText("Ready to record");});next.setOnErrorListener((p,what,extra)->{stopPlayback();state.setText("This recording could not be played.");return true;});next.prepareAsync();}catch(Exception ex){stopPlayback();state.setText("This recording could not be played.");}}
    void stopPlayback(){if(player!=null){player.release();player=null;}}
    void commands(File file){Aero.dialog(activity).setTitle(file.getName()).setItems(new String[]{"Play","Stop playback","Rename","Share","Delete"},(d,n)->{if(n==0)play(file);else if(n==1){stopPlayback();state.setText("Ready to record");}else if(n==2)rename(file);else if(n==3)share(file);else Aero.dialog(activity).setTitle("Delete recording?").setMessage(file.getName()).setPositiveButton("Delete",(x,w)->{stopPlayback();state.setText(file.delete()?"Recording deleted":"Cannot delete recording");refresh();}).setNegativeButton("Cancel",null).show();}).show();}
    void rename(File file){EditText name=new EditText(activity);name.setSingleLine();name.setText(file.getName().replaceFirst("\\.m4a$",""));android.app.AlertDialog d=Aero.dialog(activity).setTitle("Rename recording").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String base=name.getText().toString().trim();if(base.isEmpty()||base.length()>80||base.contains("/")||base.contains("\\")||base.equals(".")||base.equals("..")){name.setError("Use 1–80 characters without slashes");return;}File to=new File(folder,base+".m4a");if(to.equals(file)){d.dismiss();return;}if(to.exists()||!file.renameTo(to)){name.setError("That name exists or could not be saved");return;}d.dismiss();refresh();}));d.show();}
    void share(File file){try{Uri uri=androidx.core.content.FileProvider.getUriForFile(activity,activity.getPackageName()+".eight-files",file);Intent send=new Intent(Intent.ACTION_SEND).setType("audio/mp4").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("Recording",uri));activity.startActivity(Intent.createChooser(send,"Share or save recording"));}catch(ActivityNotFoundException|IllegalArgumentException ex){state.setText("No app is available to receive this recording.");}}
    void pause(){stop("Recording saved when leaving the screen");stopPlayback();}
    @Override public void onVisibilityAggregated(boolean visible){super.onVisibilityAggregated(visible);if(!visible&&record!=null)pause();}
    void close(){if(closed)return;pause();closed=true;main.removeCallbacksAndMessages(null);}
}
